def sha256_file(path, chunk_size=1 << 20):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(chunk_size), b""):
            h.update(chunk)
    return h.hexdigest()

def require_sha256(path, expected, label):
    observed = sha256_file(path)
    if observed != expected:
        raise ValueError(f"{label}: SHA-256 mismatch: {observed} != {expected}")
    return observed

def load_tiff(path):
    with tifffile.TiffFile(path) as tf:
        arr = tf.asarray()
    arr = np.asarray(arr)
    # tifffile may return HWC or CHW depending on storage layout.
    if arr.ndim == 3 and arr.shape[-1] <= 32 and arr.shape[0] > 32:
        arr = np.moveaxis(arr, -1, 0)
    return arr

def validate_six_band_scene(array, *, name="scene", exact_size=None):
    x = np.asarray(array)
    if x.ndim != 3 or x.shape[0] != 6:
        raise ValueError(f"{name}: expected (6, H, W), got {x.shape}")
    if exact_size is not None and x.shape[-2:] != (exact_size, exact_size):
        raise ValueError(f"{name}: expected spatial size {(exact_size, exact_size)}, got {x.shape[-2:]}")
    if not np.isfinite(x).all():
        raise ValueError(f"{name}: contains non-finite values")
    return np.ascontiguousarray(x.astype(np.float32))

def validate_crop_scene(array, *, name="crop scene"):
    x = np.asarray(array)
    if x.ndim != 3 or x.shape[0] != 18:
        raise ValueError(f"{name}: expected 18 date-major bands (3 dates × 6 bands), got {x.shape}")
    if x.shape[-2:] != (224, 224):
        raise ValueError(f"{name}: expected 224×224 pixels, got {x.shape[-2:]}")
    if not np.isfinite(x).all():
        raise ValueError(f"{name}: contains non-finite values")
    return np.ascontiguousarray(x.astype(np.float32))

def percentile_rgb(chw, rgb_indices=(2, 1, 0), p_low=2, p_high=98):
    x = np.asarray(chw, dtype=np.float32)[list(rgb_indices)]
    out = np.zeros_like(x)
    for i in range(3):
        band = x[i]
        finite = np.isfinite(band)
        if not finite.any():
            continue
        lo, hi = np.percentile(band[finite], [p_low, p_high])
        if hi <= lo:
            hi = lo + 1.0
        out[i] = np.clip((band - lo) / (hi - lo), 0, 1)
    return np.moveaxis(out, 0, -1)

def false_color(chw, indices=(3, 2, 1), p_low=2, p_high=98):
    return percentile_rgb(chw, indices, p_low, p_high)

def save_json(path, payload):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, default=str), encoding="utf-8")
    return path

def release_gpu(*objects):
    for obj in objects:
        try:
            del obj
        except Exception:
            pass
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()

def audit_pickle_globals(path, allowed):
    """Static pickle GLOBAL/STACK_GLOBAL inventory. Executes no pickle code."""
    data = Path(path).read_bytes()
    streams = []
    if data[:4] == b"PK\x03\x04":
        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            streams = [zf.read(name) for name in zf.namelist() if name.endswith(".pkl")]
    else:
        streams = [data]

    found = {}
    for payload in streams:
        stack = []
        for op, arg, _ in pickletools.genops(io.BytesIO(payload)):
            if op.name == "GLOBAL":
                key = arg.replace("\n", " ").replace(" ", ".", 1)
                found[key] = found.get(key, 0) + 1
            elif op.name == "STACK_GLOBAL" and len(stack) >= 2:
                key = f"{stack[-2]}.{stack[-1]}"
                found[key] = found.get(key, 0) + 1
            if op.name in ("SHORT_BINUNICODE", "BINUNICODE", "UNICODE", "SHORT_BINSTRING", "BINSTRING"):
                stack.append(arg)
            else:
                stack.append(None)

    violations = sorted(k for k in found if k not in allowed)
    report = {"globals": sorted(found), "violations": violations}
    if violations:
        raise ValueError(f"{Path(path).name}: pickle globals outside the allow-list: {violations}")
    return report

